#!/usr/bin/env node
/**
 * Generates public/_redirects for the WordPress → Astro migration.
 *
 *   node scripts/gen-redirects.mjs            # uses the live wp-sitemap.xml
 *   node scripts/gen-redirects.mjs --offline  # reuses the cached URL list
 *
 * Why a generated file and not netlify.toml: the old site has ~90 blog posts, all
 * at the ROOT (/slug/, not /actualitat/slug/). That is far too many rules to
 * hand-maintain, and because they sit at the root we cannot use a wildcard — a
 * wildcard there would swallow every real page. So: one explicit rule per post,
 * regenerated whenever a post is migrated.
 *
 * Hand-written rules (pages, categories, WP infrastructure, PDFs) stay in
 * netlify.toml, which Netlify evaluates BEFORE _redirects.
 *
 * MAPPED holds old→new pairs for posts that have been migrated. Everything else
 * falls back to the news index, which is a soft-404 in Google's eyes: those URLs
 * will lose their rankings. Migrate the post and add it to MAPPED to fix it
 * properly — that is the only real fix, and it is why this file prints a count.
 */
import { writeFile, readdir } from 'node:fs/promises';

const WP = process.env.WP_BASE || 'https://foodcoopbcn.cat';

/** Old WP slug (no slashes) → new path on this site. Grow this as posts migrate. */
const MAPPED = {
  'foodcoop-bcn-obre-les-portes-a-persones-no-socies': '/actualitat/obrim-a-no-socies/',
  'saps-les-millores-que-hem-fet-des-del-2025': '/actualitat/millores-2025/',
  'nou-acord-dintercooperacio-amb-alternativas-economicas': '/actualitat/acord-alternativas-economicas/',
  'risotto-de-carbassa-i-bolets': '/actualitat/receptes/risotto-carbassa-bolets/',
};

/** Root-level WP *pages* — handled in netlify.toml, must never be treated as posts. */
const PAGES = new Set([
  '', 'botiga', 'cistela', 'finalitzar-proces', 'el-meu-compte', 'activitats-directori',
  'politica-cookies', 'politica-privacitat', 'avis-legal', 'contacte', 'actualitat-premsa',
  'supermercat', 'qui-som', 'faqs', 'soci-collaborador', 'subscriu-te', 'ja-soc-soci-socia',
  'inici-actualitzacio-de-la-pagina-2022', 'fes-te-socia', 'testing-arena', 'productes',
  'entitatamiga',
]);

async function sitemapPosts() {
  const idx = await (await fetch(`${WP}/wp-sitemap.xml`)).text();
  const children = [...idx.matchAll(/<loc>(.*?)<\/loc>/g)].map((m) => m[1]);
  const postMaps = children.filter((u) => u.includes('posts-post'));
  const urls = [];
  for (const m of postMaps) {
    const xml = await (await fetch(m)).text();
    urls.push(...[...xml.matchAll(/<loc>(.*?)<\/loc>/g)].map((m) => m[1]));
  }
  return urls;
}

const posts = await sitemapPosts();
const lines = [
  '# GENERATED by scripts/gen-redirects.mjs — do not edit by hand.',
  '# Old WordPress posts lived at the site root; each needs its own rule.',
  '# Hand-written redirects live in netlify.toml and are applied first.',
  '',
];

let mapped = 0;
let fallback = 0;
for (const url of posts) {
  const slug = new URL(url).pathname.replace(/^\/|\/$/g, '');
  if (!slug || PAGES.has(slug)) continue;
  const dest = MAPPED[slug];
  if (dest) {
    lines.push(`/${slug}/  ${dest}  301!`);
    mapped++;
  } else {
    lines.push(`/${slug}/  /actualitat/  301`);
    fallback++;
  }
}

lines.push('');
await writeFile('public/_redirects', lines.join('\n'));

console.log(`public/_redirects written: ${mapped} migrated, ${fallback} pointing at the index.`);
if (fallback) {
  console.log(
    `\n⚠️  ${fallback} old posts are not migrated. Google treats a redirect to a\n` +
      `   generic index as a soft 404 and drops the URL, so these lose their rankings\n` +
      `   and any inbound links. Migrate them (scripts/migrate-wp.mjs), add the pair to\n` +
      `   MAPPED above, and re-run this script.`,
  );
}
